/**
 * Columns for the cabinets list table.
 * Partially generated by AI, to be replaced with a real API call later.
 */
import { createColumnHelper } from "@tanstack/react-table"
import { DataTableColumnHeader } from "@/shared/components/data-table"
import type { GroupType, SettingsGroupRow } from "../types/settingsList"
import { ListRowActions } from "./ListRowActions"
import {
  Avatar,
  AvatarFallback,
  AvatarGroup,
  AvatarGroupCount,
  AvatarImage,
} from "@/shared/components/ui/avatar"

const columnHelper = createColumnHelper<SettingsGroupRow>()

export const settingGroupColumns = [
  columnHelper.accessor("name", {
    id: "cabinet",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Group Name" />
    ),
    meta: {
      headerClassName: "",
      cellClassName: "align-middle",
    },
    enableSorting: false,
    cell: ({ row }) => (
      <div className="flex items-center gap-2.5">
        <div className="w-12.5 h-12.5">
          {getIconsHelper(row.original.type)}
        </div>
        <div className="flex min-w-0 flex-col gap-0.5">
          <h6 className="truncate font-semibold">{row.original.name}</h6>
          <div className="truncate">{row.original.description}</div>
        </div>
      </div>
    ),
  }),
  columnHelper.accessor("cabinetsCount", {
    id: "cabinet",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Cabinets" />
    ),
    meta: {
      headerClassName: "",
      cellClassName: "align-middle",
    },
    enableSorting: false,
    cell: ({ row }) => (
      <div className="flex min-w-0 flex-col gap-0.5">
        <span className="truncate text-accent-foreground">{row.original.cabinetsCount}</span>
      </div>
    ),
  }),
  columnHelper.accessor("members", {
    id: "cabinet",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Members" />
    ),
    meta: {
      headerClassName: "",
      cellClassName: "align-middle",
    },
    enableSorting: false,
    cell: ({ row }) => (
      <div className="flex min-w-0 flex-col gap-0.5">
        <AvatarGroup className="grayscale">
          {row.original.members.avatarUrls.map((url, index) => (
            <Avatar key={index}>
              <AvatarImage src={url} alt={`Member ${index + 1}`} />
              <AvatarFallback>
                {`M${index + 1}`}
              </AvatarFallback>
            </Avatar>
          ))}

          {row.original.members.additionalCount > 0 && (
            <AvatarGroupCount>
              +{row.original.members.additionalCount}
            </AvatarGroupCount>
          )}
        </AvatarGroup>
      </div>
    ),
  }),
  columnHelper.accessor("lastUpdated", {
    id: "cabinet",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Last Updaid" />
    ),
    meta: {
      headerClassName: "",
      cellClassName: "align-middle",
    },
    enableSorting: false,
    cell: ({ row }) => (
      <div className="flex min-w-0 flex-col gap-0.5">
        <span className="truncate font-semibold text-accent-foreground">{row.original.lastUpdated.date}</span>
        <span className="truncate font-medium">{row.original.lastUpdated.by}</span>
      </div>
    ),
  }),
  columnHelper.display({
    id: "actions",
    header: "Actions",
    enableSorting: false,
    meta: {
      headerClassName: "text-center",
      cellClassName: "",
    },
    cell: ({ row }) => <ListRowActions row={row.original} />,
  }),
]
